79	    /**
80	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
81	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
82	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
