133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        List<String> missingFields = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missingFields.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missingFields.add("lastName");
142	        }
143	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
144	        if (isBlank(normalizedAddress)) {
145	            missingFields.add("address");
146	        }
147	        if (isBlank(ownerFieldsDto.getCity())) {
148	            missingFields.add("city");
149	        }
150	        if (isBlank(ownerFieldsDto.getTelephone())) {
151	            missingFields.add("telephone");
152	        }
153	        if (!missingFields.isEmpty()) {
154	            throw new MissingOwnerFieldsException(missingFields);
155	        }
156	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
157	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
158	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
159	            throw new FutureRegistrationDateException(
160	                "registrationDate must not be later than the server date");
161	        }
162	        LocalDate registrationDate = toBusinessDay(
163	            suppliedRegistrationDate != null
164	                ? suppliedRegistrationDate
165	                : LocalDate.now());
166	        long registeredOnDay = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
168	            .count();
169	        if (registeredOnDay >= 100) {
170	            throw new DailyRegistrationLimitException(
171	                "100 or more owners have already been registered today");
172	        }
173	        boolean bulkSignupWarning = registeredOnDay > 80;
174	        String city = ownerFieldsDto.getCity();
175	        long ownersInCity = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
177	            .count();
178	        if (ownersInCity >= 50) {
179	            throw new CityAtCapacityException(
180	                "the owner's city already contains 50 or more owners");
181	        }
182	        ownerFieldsDto.setAddress(normalizedAddress);
183	        String telephone = toE164(ownerFieldsDto.getTelephone());
184	        ownerFieldsDto.setTelephone(telephone);
185	        String email = normalizeEmail(ownerFieldsDto.getEmail());
186	        ownerFieldsDto.setEmail(email);
187	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
188	        String postcode = ownerFieldsDto.getPostcode();
189	        // Deterministic household id: owners with the same normalized last name and postcode
190	        // share it automatically, regardless of creation order. It is no longer created by the
191	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
192	        String householdId = householdId(lastName, postcode);
193	        // The household is keyed on (last name, postcode), so its existing members are the
194	        // existing owners with the same computed household id. Both the duplicate block and the
195	        // household size below key off this value.
196	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> householdId.equals(
198	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
199	            .toList();
200	        // Household duplicate block: a second owner in an existing household is rejected as a
201	        // household duplicate (409) unless the request opts in via 'sharesHousehold'. Opting in
202	        // only bypasses this block; the owner is then created as a declared household member.
203	        if (!householdMembers.isEmpty()
204	            && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
205	            throw new DuplicateHouseholdException(
206	                "an owner with the same last name and postcode already exists");
207	        }
208	        // Single, consolidated duplicate check: reject only when the new owner's whole
209	        // derived identity key (telephone|email|householdId) equals an existing owner's.
210	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
211	        boolean identityInUse = this.clinicService.findAllOwners().stream()
212	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
213	                existing.getTelephone(), existing.getEmail(),
214	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
215	        if (identityInUse) {
216	            throw new DuplicateIdentityException(
217	                "an owner with the same identity key already exists");
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
221	        owner.setRegistrationDate(registrationDate);
222	        owner.setCustomerCode(
223	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
224	        owner.setHouseholdId(householdId);
225	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
226	        owner.setBulkSignupWarning(bulkSignupWarning);
227	        // Household size after this create: existing members plus the owner being created.
228	        owner.setHouseholdSize(householdMembers.size() + 1);
229	        // A declared household member is not a suspected duplicate, and no other create path
230	        // reaches here for a same-household owner, so a created owner is never flagged.
231	        owner.setPossibleDuplicate(false);
232	        owner.setPossibleDuplicateOf(null);
233	        this.clinicService.saveOwner(owner);
234	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
235	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
236	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
237	            ownerDto.getMembershipLevel());
238	        headers.setLocation(UriComponentsBuilder.newInstance()
239	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
240	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
241	    }
