341	    /**
342	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
343	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
344	     * to the effective registration date (whether supplied in the request or defaulted to the server
345	     * date), so every value derived from the registration date sees the adjusted business day.
346	     */
347	    private static LocalDate toBusinessDay(LocalDate date) {
348	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
349	            date = date.plusDays(1);
350	        }
351	        return date;
352	    }
