354	    /**
355	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
356	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
357	     * lower-cased so that last names are compared case-insensitively.
358	     */
359	    private static String normalizeHousehold(String value) {
360	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
361	    }
362	
363	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
364	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
365	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
366	
367	    /**
368	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
369	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
370	     * upper-cased, and common street-type abbreviations are expanded token-by-token
371	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
372	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
373	     * used for every address comparison (household-duplicate detection and the shared household id).
374	     */
375	    private static String normalizeAddress(String value) {
376	        if (value == null) {
377	            return "";
378	        }
379	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
380	        if (collapsed.isEmpty()) {
381	            return "";
382	        }
383	        String[] tokens = collapsed.split(" ");
384	        StringBuilder sb = new StringBuilder();
385	        for (int i = 0; i < tokens.length; i++) {
386	            if (i > 0) {
387	                sb.append(' ');
388	            }
389	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
390	        }
391	        return sb.toString();
392	    }
393	
394	    /**
395	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
396	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
397	     * deterministic function of the normalized last name and postcode, so every owner that shares
398	     * those values maps to the same identifier regardless of creation order. A {@code null}
399	     * postcode contributes the empty string.
400	     */
401	    private static String householdId(String normalizedLastName, String postcode) {
402	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
403	        return sha256Hex12(key);
404	    }
405	
406	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
407	    private static String sha256Hex12(String s) {
408	        try {
409	            byte[] digest = MessageDigest.getInstance("SHA-256")
410	                .digest(s.getBytes(StandardCharsets.UTF_8));
411	            StringBuilder sb = new StringBuilder(12);
412	            for (int i = 0; i < 6; i++) {
413	                sb.append(String.format("%02x", digest[i]));
414	            }
415	            return sb.toString();
416	        }
417	        catch (NoSuchAlgorithmException e) {
418	            throw new IllegalStateException("SHA-256 not available", e);
419	        }
420	    }
421	
422	    /**
423	     * Builds the {@code customerCode} assigned to a new owner, formatted
424	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
425	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
426	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
427	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
428	     * pure function of the owner's own identity fields.
429	     */
430	    private static String customerCode(String postcode, String telephone, String lastName) {
431	        String region = LocalityDeriver.region(postcode);
432	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
433	            + (lastName == null ? "" : lastName));
434	        return region + "-" + hash8;
435	    }
436	
437	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
438	    private static String sha256Hex8(String s) {
439	        try {
440	            byte[] digest = MessageDigest.getInstance("SHA-256")
441	                .digest(s.getBytes(StandardCharsets.UTF_8));
442	            StringBuilder sb = new StringBuilder(8);
443	            for (int i = 0; i < 4; i++) {
444	                sb.append(String.format("%02X", digest[i]));
445	            }
446	            return sb.toString();
447	        }
448	        catch (NoSuchAlgorithmException e) {
449	            throw new IllegalStateException("SHA-256 not available", e);
450	        }
451	    }
452	
453	    /**
454	     * Counts the existing owners that share the given first name and last name, compared
455	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
456	     * owner currently being created is saved), so it reflects how many namesakes preceded the
457	     * new owner.
458	     */
459	    private int countNamesakes(String firstName, String lastName) {
460	        return (int) this.clinicService.findAllOwners().stream()
461	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
462	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
463	            .count();
464	    }
