466	    /**
467	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
468	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
469	     * national one, a single leading {@code '0'} is dropped, and the default country code
470	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
471	     * national number must have the length required by its country code ({@code '+61'} requires 9
472	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
473	     * raised (reported to the client as 400).
474	     */
475	    private static String toE164(String telephone) {
476	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
477	        String digits;
478	        if (cleaned.startsWith("+")) {
479	            digits = cleaned.substring(1);
480	        } else {
481	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
482	            digits = "61" + national;
483	        }
484	        if (!digits.matches("[0-9]{8,15}")) {
485	            throw new InvalidTelephoneException(
486	                "telephone must form a valid E.164 number with 8 to 15 digits");
487	        }
488	        validateNationalLength(digits);
489	        return "+" + digits;
490	    }
491	
492	    /** National-number length required for each supported country code (digits after the code). */
493	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
494	        "61", 9, "1", 10);
495	
496	    /**
497	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
498	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
499	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
500	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
501	     */
502	    private static void validateNationalLength(String digits) {
503	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
504	            String code = entry.getKey();
505	            if (digits.startsWith(code)) {
506	                int nationalLength = digits.length() - code.length();
507	                if (nationalLength != entry.getValue()) {
508	                    throw new InvalidTelephoneException(
509	                        "telephone national number must have " + entry.getValue()
510	                            + " digits for country code +" + code);
511	                }
512	                return;
513	            }
514	        }
515	    }
516	
517	    /**
518	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
519	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
520	     * any 4-digit postcode.
521	     */
522	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
523	        "NSW", new int[] {2000, 2099},
524	        "VIC", new int[] {3000, 3099},
525	        "QLD", new int[] {4000, 4099});
526	
527	    /**
528	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
529	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
530	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
531	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
532	     * no known region accepts any 4-digit postcode. A violation raises an
533	     * {@link InvalidPostcodeException} (reported to the client as 400).
534	     */
535	    private static void validatePostcode(String city, String postcode) {
536	        if (isBlank(postcode)) {
537	            return;
538	        }
539	        if (!postcode.matches("[0-9]{4}")) {
540	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
541	        }
542	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
543	        if (range == null) {
544	            return;
545	        }
546	        int value = Integer.parseInt(postcode);
547	        if (value < range[0] || value > range[1]) {
548	            throw new InvalidPostcodeException(
549	                "postcode is out of range for the owner's city region");
550	        }
551	    }
552	
553	    /**
554	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
555	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
556	     * check).
557	     */
558	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
559	        "mailinator.com", "tempmail.com", "guerrillamail.com");
560	
561	    /**
562	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
563	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
564	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
565	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
566	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
567	     * so it is stored and returned in canonical form.
568	     */
569	    private static String normalizeEmail(String email) {
570	        if (isBlank(email)) {
571	            return null;
572	        }
573	        String trimmed = email.trim();
574	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
575	            throw new InvalidEmailException("email must be a syntactically valid address");
576	        }
577	        String normalized = trimmed.toLowerCase(Locale.ROOT);
578	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
579	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
580	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
581	        }
582	        return normalized;
583	    }
584	}
